package app.lekto.ui.icons

import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.VectorGroup
import androidx.compose.ui.graphics.vector.VectorPath
import androidx.compose.ui.unit.dp
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * The generated icon set's contract (issue #184).
 *
 * The files are generated by `tools/icons/fetch.sh`, so a regeneration at
 * another Lucide tag, or with a flag missing, must not silently change the
 * geometry `docs/design.md` §5 depends on: a 24-unit grid, a 2-unit stroke,
 * round caps and joins. Only directional icons mirror in a right-to-left
 * layout; a global `--auto-mirror=true` would mirror the whole set and is caught
 * here.
 */
class LektoIconsTest {

    /** The pack by its generated name, so a missing or renamed icon is visible. */
    private val icons: Map<String, ImageVector> = mapOf(
        "ALargeSmall" to LektoIcons.ALargeSmall,
        "ArrowLeft" to LektoIcons.ArrowLeft,
        "Bookmark" to LektoIcons.Bookmark,
        "BookOpen" to LektoIcons.BookOpen,
        "ChevronLeft" to LektoIcons.ChevronLeft,
        "ChevronRight" to LektoIcons.ChevronRight,
        "Import" to LektoIcons.Import,
        "Search" to LektoIcons.Search,
        "Settings" to LektoIcons.Settings,
        "Trash" to LektoIcons.Trash,
        "Volume2" to LektoIcons.Volume2,
        "X" to LektoIcons.X,
    )

    @Test
    fun `every icon is a 24 dp Lucide stroke drawing`() {
        assertEquals(ICON_COUNT, icons.size, "the committed set is twelve icons")
        for ((name, icon) in icons) {
            assertEquals(gridSize, icon.defaultWidth, "$name width")
            assertEquals(gridSize, icon.defaultHeight, "$name height")
            assertEquals(gridSize.value, icon.viewportWidth, "$name viewport width")
            assertEquals(gridSize.value, icon.viewportHeight, "$name viewport height")
            val paths = icon.root.strokedPaths()
            assertTrue(paths.isNotEmpty(), "$name has a path")
            for (path in paths) {
                assertNotNull(path.stroke, "$name path stroke")
                assertEquals(STROKE_WIDTH, path.strokeLineWidth, "$name stroke width")
                assertEquals(StrokeCap.Round, path.strokeLineCap, "$name stroke cap")
                assertEquals(StrokeJoin.Round, path.strokeLineJoin, "$name stroke join")
            }
        }
    }

    @Test
    fun `only the back arrow mirrors in a right-to-left layout`() {
        val mirrored = icons.filterValues { it.autoMirror }.keys
        assertEquals(setOf("ArrowLeft"), mirrored)
    }

    /** The generated icons are flat; recurse anyway so a nested pack would still be checked. */
    private fun VectorGroup.strokedPaths(): List<VectorPath> = flatMap { node ->
        when (node) {
            is VectorPath -> listOf(node)
            is VectorGroup -> node.strokedPaths()
        }
    }

    private companion object {
        /** Lucide's grid and stroke (`docs/design.md` §5). */
        const val ICON_COUNT = 12
        val gridSize = 24.dp
        const val STROKE_WIDTH = 2f
    }
}
